 theory=['INT เหมาะกับรหัสตัวเลข VARCHAR เหมาะกับชื่อและเบอร์โทรที่ต้องรักษาเลขศูนย์ DATE ใช้วันที่ และ DECIMAL(10,2) ใช้ยอดเงินที่ต้องการทศนิยมแน่นอน PK ต้องไม่ซ้ำและไม่เป็น NULL', 'FK ของ Orders.CustomerID อ้างอิง Customers.CustomerID เพื่อบังคับว่าลูกค้าที่ระบุต้องมีอยู่จริง ต้องสร้างตารางแม่ก่อนตารางลูกและเลือกชนิดรหัสให้เข้ากัน แม่แบบนี้มีช่อง ___ ต้องเติมก่อนรัน'],
 steps=['อ่านเอกสารอ้างอิงแล้วเปิดแม่แบบ เก็บสำเนา Case06_รหัสนักเรียน.sql ตรวจว่าทำงานใน db_city_case06 เท่านั้น', 'เติม Customers.CustomerID เป็น INT, CustomerName เป็น VARCHAR(100), Phone เป็น VARCHAR(20) และ PRIMARY KEY ใช้ CustomerID', 'เติม Orders.OrderID และ CustomerID เป็น INT, OrderDate เป็น DATE, TotalAmount เป็น DECIMAL(10,2) และ PRIMARY KEY ใช้ OrderID', 'เติม FOREIGN KEY (CustomerID) REFERENCES Customers(CustomerID) ใน Orders ค้น ___ ทั้งไฟล์และตรวจว่าไม่เหลือก่อนรัน', 'รัน CREATE DATABASE และ USE ตามแม่แบบ จากนั้นรัน CREATE TABLE Customers ก่อน Orders ตรวจโครงสร้างด้วย SHOW CREATE TABLE ของทั้งสองตาราง', "เพิ่มตารางแม่ก่อนด้วย INSERT INTO Customers VALUES (1,'Mali','0812340001'); แล้วเพิ่ม INSERT INTO Orders VALUES (101,1,'2026-11-24',250.00); ตรวจ SELECT ทั้งสองตาราง", "ทดลอง INSERT INTO Customers VALUES (1,'Other','0812340002'); ซึ่งใช้ PK ซ้ำ ต้องถูกปฏิเสธ บันทึกข้อความ error โดยไม่เปลี่ยน PK เพื่อหลบการตรวจ", "ทดลอง INSERT INTO Orders VALUES (102,999,'2026-11-24',100.00); ซึ่งอ้างลูกค้าที่ไม่มีอยู่ ต้องถูกปฏิเสธ แล้วตรวจว่าไม่มี OrderID 102 ถูกเพิ่ม", 'หากสร้าง FK ไม่ผ่าน ให้ตรวจชื่อคอลัมน์ ชนิดข้อมูล คีย์ของตารางแม่ และการใช้ InnoDB หากมีตารางจากการรันบางส่วน ให้ตรวจโครงสร้างเดิมก่อนแก้', 'บันทึกชนิดข้อมูลที่เลือก ผลทดสอบผ่านและไม่ผ่าน พร้อมสคริปต์เติมครบและภาพ SHOW CREATE TABLE ลงใบงาน'],
 checks=['แม่แบบไม่เหลือ ___ และสร้าง 2 ตารางได้','Phone ของลูกค้า 1 ยังมีเลขศูนย์นำหน้า','ข้อมูลอ้างอิงถูกเพิ่มได้','PK ซ้ำและ CustomerID 999 ถูกปฏิเสธ'],
 skill=['ถ้าเก็บ Phone เป็น INT จะกระทบข้อมูลตัวอย่างอย่างไร','เหตุใดการเพิ่ม OrderID 102 จึงต้องถูกปฏิเสธ และต้องแก้ข้อมูลที่ใดให้สอดคล้อง'],
 research=['ค้นคว้าความต่างของ DECIMAL กับ FLOAT สำหรับเงิน พร้อมตัวอย่างผลกระทบ','ค้นหา ON DELETE RESTRICT และ CASCADE เปรียบเทียบผลต่อข้อมูลลูก'],
