 theory=['INSERT เพิ่มแถว UPDATE เปลี่ยนค่าของแถว และ DELETE ลบแถว WHERE ระบุขอบเขตที่ต้องการ หากละ WHERE อาจเปลี่ยนทั้งตาราง ก่อน UPDATE หรือ DELETE ให้ใช้ SELECT เงื่อนไขเดียวกันตรวจเป้าหมาย', 'Starter มีสินค้า 5 แถว ProductID 3 ราคา 1000 และ ProductID 4 กับ 5 มี SalesCount เป็นศูนย์ การรัน Starter ซ้ำจะล้างงานใน schema ฝึกนี้ จึงรันเฉพาะตอนเริ่มและสำรอง SQL คำตอบแยกไว้'],
 steps=['ดาวน์โหลดและเปิด Starter ใน Workbench อ่านคำเตือนแล้วรันทั้งไฟล์เฉพาะ db_city_case07 ต้องได้ Products 5 แถว', 'เปิด SQL tab ใหม่ พิมพ์ USE db_city_case07; และบันทึกเป็น Case07_รหัสนักเรียน.sql รัน SELECT * FROM Products ORDER BY ProductID; เก็บผลก่อนทดลอง', "เพิ่มสินค้าใหม่ด้วย INSERT INTO Products (ProductID,ProductName,Price,SalesCount) VALUES (6,'Pen',20,1),(7,'Folder',40,1); แล้วตรวจว่ามี 7 แถว", 'ก่อนลดราคา รัน SELECT * FROM Products WHERE ProductID=3; ต้องพบหนึ่งแถวและราคา 1000 หากไม่ตรงให้ตรวจว่าไม่ได้รันทดลองไปแล้ว', 'เขียน UPDATE Products SET Price=Price*0.5 WHERE ProductID=3; รันเพียงครั้งเดียว แล้ว SELECT ตรวจว่าราคาเป็น 500 ไม่ใช่การแก้ทุกสินค้า', 'ก่อนลบ รัน SELECT * FROM Products WHERE SalesCount=0; จดรหัสและจำนวนแถวที่จะลบ ต้องพบ ProductID 4 และ 5 จากข้อมูลตั้งต้น', 'รัน DELETE FROM Products WHERE SalesCount=0; แล้วตรวจ SELECT ทั้งตาราง ต้องเหลือ 5 แถวเมื่อเพิ่ม 6 และ 7 ตามกำหนด', 'หาก Safe Updates ปฏิเสธ DELETE ให้ใช้ WHERE ProductID IN (4,5) AND SalesCount=0 หลังตรวจเป้าหมายแล้ว ไม่ปิดโหมดป้องกันทั้งระบบเพื่อข้ามการตรวจ', 'เก็บคำสั่งที่รันจริง จำนวนแถวที่เปลี่ยน และภาพก่อนหลัง ถ้าลดราคาซ้ำโดยไม่ตั้งใจให้บันทึกเหตุการณ์ก่อนเริ่มใหม่จาก Starter', 'บันทึก SQL และใบงานโดยแยกจาก Starter ส่งหลักฐานครบ INSERT UPDATE DELETE'],
 checks=['เริ่มต้น 5 แถวและเพิ่ม ProductID 6 กับ 7 สำเร็จ','ProductID 3 เปลี่ยนจาก 1000 เป็น 500','ลบเฉพาะ ProductID 4 และ 5 ตามเงื่อนไข','ผลสุดท้ายเหลือ 5 แถว'],
