 steps=['รันชุดข้อมูลใน db_city_case12 เปิด SQL tab คำตอบแล้ว USE db_city_case12; ตรวจว่ามี Employees, Customers และ Orders', 'รัน SELECT AVG(Salary) AS AverageSalary FROM Employees; จดค่าที่ได้และตรวจว่ามีเพียงหนึ่งแถวหนึ่งคอลัมน์', 'เขียน SELECT EmployeeID,FirstName,Salary FROM Employees WHERE Salary > (SELECT AVG(Salary) FROM Employees); ไม่แทน Subquery ด้วยตัวเลข', 'ตรวจผลแต่ละแถวว่า Salary สูงกว่าค่าที่จดในขั้นก่อน บันทึกจำนวนแถวโดยไม่เปลี่ยนข้อมูลตั้งต้น', 'รัน SELECT CustomerID FROM Orders; สังเกตว่ารหัสลูกค้าอาจซ้ำได้เพราะสั่งซื้อหลายครั้ง', 'เขียน SELECT CustomerID,CustomerName FROM Customers WHERE CustomerID IN (SELECT CustomerID FROM Orders); ต้องได้ลูกค้า 3 คน', 'เขียนแบบ EXISTS โดยเทียบ Orders.CustomerID กับ Customers.CustomerID แล้วเปรียบเทียบรายชื่อกับผล IN ต้องตรงกันสำหรับชุดนี้', 'หากขึ้น Subquery returns more than 1 row ให้ตรวจว่าใช้ = กับ SELECT ที่คืนหลายค่าอยู่หรือไม่ เลือก IN เมื่อต้องเทียบชุดค่า ห้ามสุ่มใส่ LIMIT เพื่อซ่อนปัญหา', 'บันทึกค่าเฉลี่ย SQL ของทั้งสองภารกิจ จำนวนแถว และภาพผลลัพธ์ในส่วนที่ 6', 'บันทึก Case12_รหัสนักเรียน.sql แล้วส่งพร้อมใบงานและคำอธิบายว่าคำสั่งชั้นในส่งค่าใดให้ชั้นนอก'],
 checks=['คำสั่ง AVG คืนหนึ่งค่า','พนักงานทุกแถวมี Salary มากกว่าค่าเฉลี่ย','IN เลือกลูกค้าที่ซื้อได้ 3 คน','EXISTS ให้รายชื่อเดียวกับ IN'],
 skill=['ทำไมเงื่อนไขเงินเดือนควรใช้ AVG ใน Subquery แทนตัวเลขที่จดไว้','ถ้า Subquery คืน CustomerID หลายแถว เหตุใด = จึงใช้แทน IN ไม่ได้ในกรณีนี้'],
